-- Errata reading for O03: Age = latest reported age (most recent demographic_updates age_reported received by the as-of date, else the roster age_reported); everything else as the reference.
WITH r AS MATERIALIZED (SELECT patient, stream, payload FROM records WHERE stream IN ('conditions','pharmacy_dispenses')), op AS (SELECT DISTINCT patient FROM r WHERE stream='conditions' AND (lower(json_extract(payload,'$.description')) LIKE '%osteoporosis%' OR coalesce(json_extract(payload,'$.icd10'),'') LIKE 'M80%' OR coalesce(json_extract(payload,'$.icd10'),'') LIKE 'M81%')), bp AS (SELECT DISTINCT patient FROM r WHERE stream='pharmacy_dispenses' AND json_extract(payload,'$.status')='dispensed' AND (lower(json_extract(payload,'$.medication_name')) LIKE '%alendron%' OR lower(json_extract(payload,'$.medication_name')) LIKE '%risedron%' OR lower(json_extract(payload,'$.medication_name')) LIKE '%ibandron%' OR lower(json_extract(payload,'$.medication_name')) LIKE '%zoledron%')) SELECT COUNT(*) AS count FROM patients p JOIN op ON op.patient=p.id WHERE json_extract(p.payload,'$.sex_reported')='F' AND coalesce((SELECT json_extract(du_.payload,'$.age_reported') FROM records du_ WHERE du_.stream='demographic_updates' AND du_.patient=p.id AND json_extract(du_.payload,'$.age_reported') IS NOT NULL ORDER BY json_extract(du_.payload,'$.age_reference_date') DESC LIMIT 1), json_extract(p.payload,'$.age_reported'))>=65 AND p.id NOT IN (SELECT patient FROM bp);
